#!/bin/zsh
# Claude Code CC Aliases
# Terminal shortcuts to launch Claude with team-specific agent personas
# Generated by AITeamForge installer — uses direct --system-prompt passing
# NOTE: stdin piping (echo | claude --system-prompt -) breaks in tmux contexts
# This file is a template — {{ORG_NAME}}, {{ORG_SLUG}}, etc. are substituted
# at install time by the AITeamForge installer. Do not edit the rendered copy.

# Installation directory (substituted during install)
AITEAMFORGE_DIR="{{AITEAMFORGE_DIR}}"

# XACA-1312: the credential-routing core (design doc §1.1, §6) — the SAME
# file dev claude_code_cc_aliases.sh sources, shipped here so a consumer's
# cc/cc-*/ccc launches actually apply the team's declared ai.credential
# instead of always billing the machine login. Tap-Only-Edit: intentional
# (this template is not in sync-tap.sh's mirror map — grep confirms only
# comment hits — so this source line and the _cc_launch/cc/ccc wiring below
# are native to this file, not derived from the canonical launcher).
#
# Fail-closed on a missing/broken core: a partial upgrade or a non-zsh shell
# must refuse cc/cc-*/ccc rather than silently launch unrouted (design §6,
# "if the core fails to load"). _cc_routing_core_missing is what every
# wired launch site below checks before doing anything else.
#
# XACA-1312 fix round 1 (bot review, PR #957): the message below has always
# promised that AITEAMFORGE_ALLOW_DEFAULT_OAUTH=1 launches on the machine
# login even when the core itself is missing -- design §6's own escape
# hatch. Until this fix the function returned 1 unconditionally, so the
# override did nothing here (verified: core absent + override set + `ccc`
# still refused). Every call site below now branches on THIS return value
# instead of hardcoding `return 1` -- see each site's own comment.
#
# XACA-1312 fix round 3 (bot review, PR #957, finding 022): "missing" now
# covers PARTIAL too. Round 1/2 shimmed each of the three core functions
# independently ("if this ONE function isn't defined, shim just it"). A
# truncated/mid-parse-error core (interrupted upgrade copy) can define an
# EARLY function like _cc_route_prepare without reaching a LATER one like
# _cc_run_claude_with_auth -- every call site below used
# `command -v _cc_route_prepare` as its "is the core loaded" signal, so
# that half-loaded state read as "loaded", resolved a REAL token, and then
# handed it to the runner shim (still installed, since only
# _cc_run_claude_with_auth was missing) -- which silently dropped it and
# launched bare `claude` on the machine login while the banner/recorder
# still claimed the team account. The core itself now exposes
# _cc_routing_core_complete (see its own comment in cc-account-routing.sh)
# as the single completeness gate; every call site below uses THAT instead
# of checking any one function's presence, and this file's own fallback
# shims are installed together, never independently, so a partial core's
# leftover (untrustworthy) definitions are always fully discarded.
_cc_routing_core_missing() {
    if [[ "${AITEAMFORGE_ALLOW_DEFAULT_OAUTH:-0}" == "1" ]]; then
        print -u2 "⚠ AITEAMFORGE_ALLOW_DEFAULT_OAUTH=1 — routing core missing/incomplete at $AITEAMFORGE_DIR/scripts/cc-account-routing.sh — this session bills the MACHINE LOGIN, not any declared team credential"
        _cc_install_core_fallback_shims
        return 0
    fi
    print -u2 "✗ routing core missing/incomplete at $AITEAMFORGE_DIR/scripts/cc-account-routing.sh — run 'aiteamforge upgrade' (or AITEAMFORGE_ALLOW_DEFAULT_OAUTH=1 to launch on the machine login)"
    return 1
}
if [[ -f "$AITEAMFORGE_DIR/scripts/cc-account-routing.sh" ]]; then
    source "$AITEAMFORGE_DIR/scripts/cc-account-routing.sh" || true
fi
# XACA-1312 fix round 3: every call site below gates on _cc_routing_core_complete,
# not on `command -v _cc_route_prepare`. When the core loads FULLY it defines
# its own real _cc_routing_core_complete (sentinel + all four required
# functions; see cc-account-routing.sh's own comment) — this file must NOT
# shadow that. Only define a fallback here when the core did not already
# supply one: a fully-missing core never reaches that far, and neither does
# a core truncated before that point, so in both cases this fallback (an
# unconditional "not complete") is the correct answer.
if ! command -v _cc_routing_core_complete >/dev/null 2>&1; then
    _cc_routing_core_complete() { return 1; }
fi
# Fallback shims, installed TOGETHER (never per-function) only when the
# core is missing/incomplete AND AITEAMFORGE_ALLOW_DEFAULT_OAUTH=1 -- see
# _cc_routing_core_missing above. Redefining all of them here unconditionally
# discards whatever a partial parse left behind, rather than trusting
# individual leftover definitions.
_cc_install_core_fallback_shims() {
    # Defense in depth (round-3 finding): a shim must never silently drop a
    # resolved credential. Every call site below skips _cc_route_prepare
    # entirely once the core is judged incomplete, so $1 is always empty in
    # normal operation -- but refuse loudly instead of launching unrouted if
    # that invariant is ever violated (e.g. a future call site change).
    _cc_run_claude_with_auth() {
        local _cc_shim_token="$1"
        shift 2
        if [[ -n "$_cc_shim_token" ]]; then
            print -u2 "✗ routing core missing/incomplete — refusing to launch: a team credential was resolved but the function needed to apply it isn't available. Aborting rather than billing the wrong account."
            return 1
        fi
        claude "$@"
    }
    # Silent no-op, matching the real function's own documented fail-soft
    # contract ("Silent no-op when the recorder is absent ... never aborts a
    # launch") -- there is no recorder to call when the core never loaded.
    _cc_record_session_account() { :; }
    # ccc's cross-account resume check. Same defense-in-depth as the runner
    # shim above: only auto-allow when NO account was actually resolved (the
    # override path's normal shape, $2 empty). If a resolved account id is
    # ever passed in anyway, refuse instead of rubber-stamping a resume this
    # shim has no way to safety-check.
    _cc_resume_account_guard() {
        local _cc_shim_resolved_id="$2"
        if [[ -n "$_cc_shim_resolved_id" ]]; then
            print -u2 "✗ routing core missing/incomplete — refusing resume: a team account was resolved but the cross-account guard needed to check it isn't available. Aborting."
            return 1
        fi
        return 0
    }
}

# ─────────────────────────────────────────────────────────────────────────────
# Core Infrastructure
# ─────────────────────────────────────────────────────────────────────────────

# Remove any existing cc/ccc aliases before defining functions
unalias cc 2>/dev/null
unalias ccc 2>/dev/null

# Encode working directory to match Claude Code's project directory naming
# /Users/darrenehlers/dev-team → -Users-darrenehlers-dev-team
_cc_encode_project_dir() {
    local dir="${1:-$(pwd)}"
    echo "$dir" | sed 's|[/ ]|-|g; s|^-||'
}

# XACA-1075: ask tmux a format question about THIS window (pane-targeted when
# $TMUX_PANE is known, so a background caller still asks about its own window).
_cc_tmux_fmt() {
    if [[ -n "$TMUX_PANE" ]]; then
        tmux display-message -t "$TMUX_PANE" -p "$1" 2>/dev/null
    else
        tmux display-message -p "$1" 2>/dev/null
    fi
}

# XACA-1074-021: session-qualified key. Sidecars are keyed per SESSION_CODE, not per
# tmux session, so two tmux sessions CAN share one (MainEvent qualifies the session
# name with the project while home-scripts/.zshrc_* re-derive SESSION_CODE
# project-less; SESSION_CODE is a plain shell variable). The key must therefore name
# its session, using ONLY facts that survive a tmux restart: the session name (the
# startup scripts recreate it) and the window name. The earlier design (016) decided
# uniqueness from a tmux session option stamped at claim time; a restart wipes it, so
# the first window to run ccc afterwards claimed the shared "-k<name>" whichever
# session it was in, and resumed its session-mate's conversation. Claim order must not
# matter, so there is no stamp-based state any more (@cc_session_code is gone: the
# qualified key makes it redundant, and no case needs it).
#   $1 = #{session_name}, $2 = raw window key/name.  Echoes the sanitized key:
#   session name == $SESSION_CODE (the canonical layout), or no SESSION_CODE  -> "<name>"
#   any OTHER session                                                         -> "<session>.<name>"
# tmux never allows "." in a session name, so the first "." of a qualified key is the
# separator; a canonical window literally named "projA.command" can still equal a
# qualified key, which the equality-based dupe check in _cc_window_key catches.
_cc_qualify_key() {
    local sname="$1" raw="$2"
    [[ -n "$raw" ]] || return 0
    if [[ -z "$SESSION_CODE" || "$sname" == "$SESSION_CODE" ]]; then
        printf '%s' "$raw" | tr -c 'A-Za-z0-9._-' '_'
    else
        printf '%s.%s' "$sname" "$raw" | tr -c 'A-Za-z0-9._-' '_'
    fi
}

# Name of session id $2 within the "<session_id> <session_name>" listing $1.
_cc_session_name_of() {
    local line
    while IFS= read -r line; do
        [[ "${line%% *}" == "$2" ]] || continue
        printf '%s' "${line#* }"
        return 0
    done <<< "$1"
    return 1
}

# XACA-1074-021: how many OTHER windows carry the qualified key $4? $1 = this window id,
# $2 = this session id, $3 = the "<session_id> <session_name>" listing, $5 = "names" to
# also compare other windows' NAMES (claiming a fresh key) or "keys" for stamped keys
# only (a window that already owns its stamp keeps it when a neighbour is merely RENAMED
# into the same name; two STAMPS that qualify equal still both yield). With no
# SESSION_CODE only our own session is compared. Names and keys come from two listings:
# either may contain any character, so neither can share a line with the other (the
# free-text field is always LAST). A session that cannot be resolved counts as a dupe.
_cc_key_dupes() {
    local wid="$1" sid="$2" sessions="$3" mine="$4" mode="$5" listing line ssid rest lwid val osn n=0
    if [[ "$mode" == names ]]; then
        listing=$(tmux list-windows -a -F '#{session_id} #{window_id} #{window_name}' 2>/dev/null)
        while IFS= read -r line; do
            ssid="${line%% *}"; rest="${line#* }"; lwid="${rest%% *}"
            [[ "$lwid" == "$wid" ]] && continue
            [[ -z "$SESSION_CODE" && "$ssid" != "$sid" ]] && continue
            val=""; [[ "$rest" == *" "* ]] && val="${rest#* }"
            osn=$(_cc_session_name_of "$sessions" "$ssid") || { n=$((n + 1)); continue; }
            [[ "$(_cc_qualify_key "$osn" "$val")" == "$mine" ]] && n=$((n + 1))
        done <<< "$listing"
    fi
    listing=$(tmux list-windows -a -F '#{session_id} #{window_id} #{@cc_window_key}' 2>/dev/null)
    while IFS= read -r line; do
        ssid="${line%% *}"; rest="${line#* }"; lwid="${rest%% *}"
        [[ "$lwid" == "$wid" || "$rest" != *" "* ]] && continue
        [[ -z "$SESSION_CODE" && "$ssid" != "$sid" ]] && continue
        val="${rest#* }"
        [[ -n "$val" ]] || continue
        osn=$(_cc_session_name_of "$sessions" "$ssid") || { n=$((n + 1)); continue; }
        [[ "$(_cc_qualify_key "$osn" "$val")" == "$mine" ]] && n=$((n + 1))
    done <<< "$listing"
    printf '%s' "$n"
}

# XACA-1075: restart-stable window key. Echoes a sanitized, session-qualified key
# (see _cc_qualify_key), or nothing when the window has no trustworthy name-based
# identity (caller falls back to the window-id). $1 = this window's #{window_id}.
# Priority:
#   a. the window user-option @cc_window_key, if set;
#   b. else, when the window name was set EXPLICITLY (a window-LOCAL
#      automatic-rename of off, i.e. `new-window -n` / `new-session -n` /
#      `rename-window`; every team startup script uses -n; XACA-1074-013) and no
#      OTHER window carries the same QUALIFIED key (XACA-1074-021: any session, any
#      sanitize-equivalent name or stamped key), lazily stamp @cc_window_key = name
#      and use it. The startup scripts
#      recreate the same session and window names after a restart, so the key
#      re-derives identically -- the option itself is LOST on restart, the names are not.
# Names that a shell/tmux sets on its own (zsh, bash, tmux, ...) are never keys:
# a hand-made window is not the same window after a restart. Reorder never moves
# a name or an option, so the XACA-0668-004 reorder-stability property holds.
# The stamp always holds the RAW window name; qualification is applied on every
# derivation (also to stamps written by earlier versions, which hold bare names).
_cc_window_key() {
    local wid="$1" key="" name="" auto="" allow="" sid="" sname="" sessions="" mine=""
    sname=$(_cc_tmux_fmt '#{session_name}')
    [[ -z "$sname" ]] && return 0
    sid=$(_cc_tmux_fmt '#{session_id}')
    [[ -n "$sid" ]] && sessions=$(tmux list-sessions -F '#{session_id} #{session_name}' 2>/dev/null)
    key=$(tmux show-options -w -v -q -t "$wid" @cc_window_key 2>/dev/null)
    if [[ -n "$key" ]]; then
        # A stamp (possibly a bare name written before XACA-1074-021) is qualified on
        # every read. Two stamps that qualify EQUAL (sanitize-equivalent session names
        # such as "p q" and "p_q") cannot be told apart: both fail closed to "-w@N".
        [[ -n "$sessions" ]] || return 0
        mine=$(_cc_qualify_key "$sname" "$key")
        (( $(_cc_key_dupes "$wid" "$sid" "$sessions" "$mine" keys) == 0 )) || return 0
    else
        # XACA-1074-013: read the WINDOW-LOCAL automatic-rename, not the effective
        # #{automatic-rename} format. The product tmux.conf sets it off GLOBALLY,
        # so the effective value is 0 for every window and a name tmux merely
        # auto-filled from the running command ("sleep") looked explicit. Measured
        # (tmux 3.6a): `new-window -n`, `new-session -n` and `rename-window` set the
        # option on the window itself; a window named by tmux has NO local value
        # even when the global one is off. `show-options -w -v -q` prints only the
        # local value (empty when unset), so empty/"on" = not explicit.
        auto=$(tmux show-options -w -v -q -t "$wid" automatic-rename 2>/dev/null)
        name=$(_cc_tmux_fmt '#{window_name}')
        case "$name" in zsh|bash|sh|dash|ksh|fish|tmux) name="" ;; esac
        # XACA-1074-014: ...and only while allow-rename is off. With allow-rename
        # ON any program in the pane can set the window name (ESC k), and tmux then
        # sets the window-local automatic-rename off exactly as `-n` does; measured
        # (tmux 3.6a): the local option, #{window_name} and the window-renamed hook
        # all look the same after the fact (the hook does not fire for `-n`, but it
        # cannot be relied on: it must pre-exist the rename). So a name is trusted
        # only while the pane cannot have been titled by a program: #{allow-rename}
        # must read 0 (the product tmux.conf sets it off). Anything else -- on, or
        # unreadable -- fails closed to the identity-guarded "-w@N" key. A name
        # stamped into @cc_window_key earlier stays authoritative (branch a above).
        allow=$(_cc_tmux_fmt '#{allow-rename}')
        # No session listing => cannot prove the key is unique => do not stamp.
        if [[ "$auto" == "off" && "$allow" == "0" && -n "$name" && -n "$sessions" ]]; then
            # Unique means the QUALIFIED, sanitized key (the filename form) is unique
            # across every session: "a b" and "a_b", "a/b" and "a|b", or two non-ASCII
            # names would all share one sidecar; and it must not equal another window's
            # already-stamped key (a window renamed INTO a name another window was
            # stamped under would adopt its session).
            mine=$(_cc_qualify_key "$sname" "$name")
            if (( $(_cc_key_dupes "$wid" "$sid" "$sessions" "$mine" names) == 0 )); then
                tmux set-option -w -t "$wid" @cc_window_key "$name" 2>/dev/null && key="$name"
            fi
        fi
    fi
    [[ -z "$key" ]] && return 0
    _cc_qualify_key "$sname" "$key"
}

# Print the sidecar key suffix for this tmux window; return non-zero outside
# tmux. Scopes saved session files to a specific tmux window so two windows
# running the same persona don't clobber each other's resume state.
#
# XACA-0668 (subitem 004): switched from the window INDEX (#I, e.g. "2") to the
# stable window-ID (#{window_id}, e.g. "@5"). The index is volatile — tmux
# reindexes windows when one is added, removed, or moved (move-window /
# renumber-windows), so a sidecar keyed by index can silently point at the wrong
# window after the layout changes. The window-id is permanent for the lifetime of
# the window, so the sidecar→window binding stays correct. '@' is filename-safe.
# The "-w" prefix is kept for continuity so the lazy migration glob can still
# locate legacy "-w<index>" files (see _cc_migrate_window_sidecar).
#
# XACA-1075: the window-id is only unique within ONE tmux server lifetime — after
# a restart tmux reissues @0, @1, ... so "-w@N" silently adopted a stranger's
# sidecar. The key is now "-k<key>" (see _cc_window_key) whenever the window has
# a restart-stable name; "-w<window_id>" remains the fallback for unnamed windows
# and is guarded at READ time (_cc_sidecar_usable) by a server-identity check.
_cc_window_suffix() {
    [[ -z "$TMUX" ]] && return 1
    local wid key
    wid=$(_cc_tmux_fmt '#{window_id}')
    [[ -z "$wid" ]] && return 1
    key=$(_cc_window_key "$wid")
    if [[ -n "$key" ]]; then
        echo "-k${key}"
    else
        echo "-w${wid}"
    fi
}

# XACA-1075: live tmux server identity (#{start_time} + #{pid} identify one
# server lifetime). Sets _CC_LIVE_START/_CC_LIVE_PID (call directly, not in
# $(...)). Returns non-zero when start_time is not a plain epoch number.
_cc_live_server_id() {
    _CC_LIVE_START=$(_cc_tmux_fmt '#{start_time}')
    _CC_LIVE_PID=$(_cc_tmux_fmt '#{pid}')
    [[ "$_CC_LIVE_START" =~ ^[0-9]+$ ]] || return 1
    [[ "$_CC_LIVE_PID" =~ ^[0-9]+$ ]] || _CC_LIVE_PID=""
    # XACA-1074-015: pin the identity epoch the first time identity-aware code
    # runs on this HOME (idempotent; every save and every provenance check
    # passes through here, so it is set before any file could be restored).
    _cc_identity_epoch >/dev/null 2>&1
    return 0
}

# XACA-1074-015: the "identity epoch" = the first moment identity-writing code ran
# on this HOME (epoch seconds, kept in ~/.claude/.cc-sidecar-identity-epoch -- a
# dotfile OUTSIDE terminal-sessions/ so no sidecar glob or sweep ever sees it).
# Every -w@N sidecar written from then on carries server_start+server_pid (the
# writer skips the file when it cannot read both: XACA-1074-022), so on a server
# that started AFTER the epoch an identity-LESS file cannot be genuine: it is a
# restore/copy/hand-made file and is unprovable (see _cc_sidecar_from_this_server
# for why the bound applies only to such servers). The marker is written once
# (mv -n, never overwritten). Echoes the epoch, or returns
# non-zero when it cannot be read or created (callers fail closed).
_cc_identity_epoch() {
    local f="${HOME}/.claude/.cc-sidecar-identity-epoch" v="" tmp=""
    if [[ ! -s "$f" ]]; then
        mkdir -p "${HOME}/.claude" 2>/dev/null || return 1
        tmp="${f}.$$"
        # XACA-1074-021: never install an EMPTY marker (a full disk makes `date >` leave
        # a zero-byte file, and an empty marker would reject every identity-less file
        # forever). An existing EMPTY marker is replaced; a non-empty one never is --
        # the -s re-check right before the mv is the only guard (no lock; the window is
        # microseconds and only a disk-full empty marker can reach this branch).
        date +%s > "$tmp" 2>/dev/null
        if [[ -s "$tmp" ]]; then
            if [[ -e "$f" && ! -s "$f" ]]; then mv -f "$tmp" "$f" 2>/dev/null
            else mv -n "$tmp" "$f" 2>/dev/null; fi
        fi
        [[ -e "$tmp" ]] && unlink "$tmp" 2>/dev/null
    fi
    IFS= read -r v < "$f" 2>/dev/null
    [[ "$v" =~ ^[0-9]+$ ]] || return 1
    echo "$v"
}

# XACA-1075: parse a sidecar into _CC_SC_{ID,NAME,DIR,START,PID,WID}. Format is
# "uuid|name|pwd|server_start|server_pid|window_id"; new fields are LAST, so
# legacy 1/2/3-field files parse with the trailing vars empty. Every reader goes
# through here (or reads with 6 vars) — a 3-var read would fold the identity
# fields into the cwd.
_cc_sidecar_read() {
    _CC_SC_ID="" _CC_SC_NAME="" _CC_SC_DIR="" _CC_SC_START="" _CC_SC_PID="" _CC_SC_WID=""
    [[ -r "$1" ]] || return 1
    IFS='|' read -r _CC_SC_ID _CC_SC_NAME _CC_SC_DIR _CC_SC_START _CC_SC_PID _CC_SC_WID < "$1" || true
    return 0
}

# File mtime as epoch seconds (GNU stat first: BSD stat rejects -c, whereas GNU
# stat accepts BSD's -f as a different, filesystem mode).
_cc_file_mtime() {
    local m
    m=$(stat -c %Y "$1" 2>/dev/null) || m=$(stat -f %m "$1" 2>/dev/null) || return 1
    [[ "$m" =~ ^[0-9]+$ ]] || return 1
    echo "$m"
}

# XACA-1075: is this sidecar provably from the CURRENT tmux server lifetime?
# Complete stored identity (server_start AND server_pid) -> must equal the live
# one. Legacy file (NO identity, written by pre-XACA-1075 code) -> the mtime proof:
# server_start < mtime. STRICTLY after the start: #{start_time} has 1s granularity,
# so a file the previous server wrote in the same second a restarted server came up
# has mtime == start_time and a ">=" test passed it (XACA-1074-015).
#
# XACA-1074-022: the identity EPOCH (_cc_identity_epoch, the first moment
# identity-writing code ran on this HOME) refines that proof, but only where it is
# SOUND. Identity-writing code never emits an identity-less file, so an identity-less
# file is "restore/copy-shaped" (backups and copies refresh the mtime) -- but only on
# a server that no pre-upgrade shell can live on, i.e. one that STARTED STRICTLY AFTER
# the epoch: every shell in it sourced the upgraded file. On a server that predates
# the epoch (the first lifetime after an upgrade) old-code shells are normal -- a
# long-lived tmux shell keeps the functions it sourced -- and one of them writes a
# genuine identity-less file on THIS server with an mtime after the epoch. 015's
# "mtime <= epoch" bound rejected exactly those files (a shared cwd then falls to
# --continue: the XACA-1074 symptom, caused by the upgrade). There, a restore is
# indistinguishable from such a write, so the original 1075 proof stands and the
# residual risk is accepted and bounded to that one lifetime. The reader must accept
# every file the CURRENT writer can produce on a live server (see _cc_save_session:
# it never writes an unprovable -w@N file).
# Partial identity (start XOR pid), unknown live identity, unreadable file or an
# unreadable epoch -> NOT provable (fail closed).
_cc_sidecar_from_this_server() {
    _cc_sidecar_read "$1" || return 1
    _cc_live_server_id || return 1
    if [[ -n "$_CC_SC_START" || -n "$_CC_SC_PID" ]]; then
        [[ -n "$_CC_SC_START" && -n "$_CC_SC_PID" ]] || return 1
        [[ "$_CC_SC_START" == "$_CC_LIVE_START" && "$_CC_SC_PID" == "$_CC_LIVE_PID" ]]
        return
    fi
    local m epoch
    m=$(_cc_file_mtime "$1") || return 1
    (( m > _CC_LIVE_START )) || return 1
    epoch=$(_cc_identity_epoch) || return 1
    # Server started after the upgrade: no old-code shell, so no genuine identity-less file.
    (( _CC_LIVE_START > epoch )) && return 1
    return 0
}

# XACA-1075: does a transcript for this session uuid exist on disk? (UUIDs are
# unique across projects, so search every project dir rather than re-deriving
# the cwd slug.)
_cc_transcript_exists() {
    local id="$1" base
    [[ "$id" =~ ^[A-Za-z0-9_-]+$ ]] || return 1
    for base in "${CLAUDE_CONFIG_DIR:-$HOME/.claude}" "$HOME/.claude"; do
        [[ -d "$base/projects" ]] || continue
        [[ -n "$(find "$base/projects" -maxdepth 2 -name "${id}.jsonl" 2>/dev/null | head -n 1)" ]] && return 0
    done
    return 1
}

# XACA-1075: read-time staleness guard. $1 = sidecar path, $2 = the suffix it
# was found under, $3 = "quiet" to suppress the notice (banner use). Returns
# non-zero — fail closed to the existing no-stored-session path — when
#   - the transcript for the stored uuid is not on disk, or
#   - the key is the "-w@N" window-id fallback and the file cannot be proven to
#     come from this tmux server lifetime (window ids restart after a server
#     restart, so a pre-restart "-w@N" file may belong to an unrelated window).
# Never resumes a stranger; never deletes or edits the file.
_cc_sidecar_usable() {
    local f="$1" sfx="$2" quiet="${3:-}"
    _cc_sidecar_read "$f" || return 1
    [[ -z "$_CC_SC_ID" ]] && return 1
    if ! _cc_transcript_exists "$_CC_SC_ID"; then
        [[ "$quiet" == "quiet" ]] || printf 'ccc: ignoring saved session %s for this window — its transcript is gone\n' "${_CC_SC_ID:0:8}" >&2
        return 1
    fi
    if [[ "$sfx" == -w@* ]] && ! _cc_sidecar_from_this_server "$f"; then
        [[ "$quiet" == "quiet" ]] || printf 'ccc: ignoring saved session %s for this window — saved under a previous tmux server (window ids restart after a restart, so %s may be a different window now)\n' "${_CC_SC_ID:0:8}" "${sfx#-w}" >&2
        return 1
    fi
    return 0
}

# XACA-1075: when ccc finds no usable sidecar, list sidecars of this SESSION_CODE
# that no live window claims and whose stored cwd matches this one, so the user
# can resume one EXPLICITLY. Never adopts anything: a shared cwd is not proof of
# ownership (XACA-1074 shape). Advisory only; prints nothing when there are none.
_cc_sidecar_stray_hint() {
    [[ -z "$SESSION_CODE" || -z "$TMUX" ]] && return 0
    local dir="$HOME/.claude/terminal-sessions" cur_sfx f base sfx m when shown=0
    local live_ids live_keys="" out=""
    cur_sfx=$(_cc_window_suffix 2>/dev/null) || cur_sfx=""
    live_ids=$(tmux list-windows -a -F '#{window_id}' 2>/dev/null)
    # @cc_window_key holds the RAW name; the "-k" suffix is its session-qualified,
    # sanitized form (XACA-1074-021), so qualify each stamp with ITS session before
    # comparing. A pre-021 bare "-k<name>" file from a non-canonical session matches
    # no live qualified key, so it stays listed here: fail closed, never adopted.
    local sline sn k
    while IFS= read -r sline; do
        [[ -n "$sline" ]] || continue
        sn="${sline#* }"
        while IFS= read -r k; do
            [[ -n "$k" ]] && live_keys="${live_keys}$(_cc_qualify_key "$sn" "$k")"$'\n'
        done < <(tmux list-windows -t "${sline%% *}" -F '#{@cc_window_key}' 2>/dev/null)
    done < <(tmux list-sessions -F '#{session_id} #{session_name}' 2>/dev/null)
    while IFS= read -r f; do
        [[ -n "$f" ]] || continue
        base="${f##*/}"
        sfx="${base#"$SESSION_CODE"}"
        case "$sfx" in -w*|-k*) ;; *) continue ;; esac
        [[ "$sfx" == "$cur_sfx" ]] && continue
        case "$sfx" in
            -k*) printf '%s\n' "$live_keys" | grep -qxF -- "${sfx#-k}" && continue ;;
            -w@*) if printf '%s\n' "$live_ids" | grep -qxF -- "${sfx#-w}" && _cc_sidecar_from_this_server "$f"; then continue; fi ;;
        esac
        _cc_sidecar_read "$f" || continue
        [[ -n "$_CC_SC_ID" && "$_CC_SC_DIR" == "$PWD" ]] || continue
        _cc_transcript_exists "$_CC_SC_ID" || continue
        m=$(_cc_file_mtime "$f") || m=""
        when=""
        [[ -n "$m" ]] && when=$(date -r "$m" '+%Y-%m-%d %H:%M' 2>/dev/null || date -d "@$m" '+%Y-%m-%d %H:%M' 2>/dev/null)
        out="${out}    ${_CC_SC_ID}  ${when:-?}  ${_CC_SC_NAME:-(unnamed)}  [${sfx}]"$'\n'
        shown=$((shown + 1))
        (( shown >= 5 )) && break
    done < <(find "$dir" -maxdepth 1 -type f -name "${SESSION_CODE}-*" -exec ls -t {} + 2>/dev/null)
    (( shown == 0 )) && return 0
    printf '\e[2mccc: unclaimed saved sessions for %s in this directory (NOT adopted automatically):\n%s    resume one explicitly with: claude --resume <uuid>\e[0m\n' "$SESSION_CODE" "$out" >&2
}

# XACA-0668 (subitem 005): lazily migrate the CURRENT window's legacy sidecar
# file to the current key.
#
# Why lazy + current-window-only: the index→window_id mapping is only reliable
# for a live window, because only the current window can read BOTH #I (its old
# key) and #{window_id} (its new key) in the same breath. A bulk sweep across
# all windows can't reconstruct which historical index produced which file once
# the layout has changed, so it could rename the wrong file. By migrating only
# the window we're actually in, on the next ccc/_cc_launch, the rename is always
# correct.
#
# XACA-1075: the target is now whatever _cc_window_suffix returns ("-k<key>" or
# "-w<window_id>"), and BOTH "-w<window_id>" and legacy "-w<index>" sources are
# considered — but only when the source is PROVABLY from this tmux server
# lifetime (_cc_sidecar_from_this_server). A "-w@N" / "-w<idx>" file that cannot
# be proven is a pre-restart stray: it is left exactly where it is (never
# adopted, never deleted — a matching cwd is not proof, XACA-1074 shape);
# _cc_sidecar_stray_hint surfaces it for an explicit resume.
#
# Behavior: if the source exists and the target does NOT, mv source→target (no
# clobber). If the target already exists, leave the source untouched (do not
# delete — avoid stranding/overwriting newer state). Outside tmux or with no
# SESSION_CODE there are no per-window keys, so this is a no-op. Never errors
# on missing files.
#
# Only the terminal-sessions sidecar is window-keyed; the per-account file
# (~/.claude/.last-session-per-account/...) is keyed by account, not window, and
# is intentionally NOT migrated here.
_cc_migrate_window_sidecar() {
    [[ -z "$TMUX" ]] && return 0
    [[ -z "$SESSION_CODE" ]] && return 0

    local new_suffix
    new_suffix=$(_cc_window_suffix) || return 0

    local dir="$HOME/.claude/terminal-sessions"
    local new_file="${dir}/${SESSION_CODE}${new_suffix}"
    [[ -e "$new_file" ]] && return 0

    # Candidate old keys, most specific first: this window's id, then its
    # legacy #I index (recomputed inline so _cc_window_suffix stays clean).
    local wid idx cand src
    wid=$(_cc_tmux_fmt '#{window_id}')
    idx=$(_cc_tmux_fmt '#I')
    for cand in "-w${wid}" "-w${idx}"; do
        [[ "$cand" == "-w" || "$cand" == "$new_suffix" ]] && continue
        src="${dir}/${SESSION_CODE}${cand}"
        [[ -f "$src" ]] || continue
        if _cc_sidecar_from_this_server "$src"; then
            mv -n "$src" "$new_file" 2>/dev/null || true
            return 0
        fi
    done
    return 0
}

# Derive a human-readable session name mirroring what the agent panel's
# MISSION section displays: kanban task → "ITEM-ID: item title" → first
# user message from the transcript. Truncated to 40 chars. Empty if none
# of the sources yield a usable value.
_cc_derive_session_name() {
    local transcript="$1"
    local name=""

    # Sources 1 & 2: kanban board (same lookup logic as get_kanban_info
    # in scripts/agent-panel-display.sh, trimmed to the fields we need).
    if typeset -f _kb_detect_context &>/dev/null; then
        local context team terminal window_name board_file window_id info
        context=$(_kb_detect_context 2>/dev/null)
        if [[ -n "$context" && "$context" != "ERROR:ERROR:0:unknown" ]]; then
            team="${context%%:*}"
            local rest="${context#*:}"
            terminal="${rest%%:*}"
            rest="${rest#*:}"
            window_name="${rest#*:}"
            board_file=$(_kb_get_board_file "$team" 2>/dev/null)
            window_id=$(_kb_get_window_id "$terminal" "$window_name" 2>/dev/null)

            if [[ -f "$board_file" && -n "$window_id" ]]; then
                info=$(_kb_jq_read "$board_file" '
                    (.activeWindows // []) as $wins |
                    (.backlog // []) as $bl |
                    ($wins | map(select(.id == $wid)) | first // null) as $aw |
                    if $aw == null then ""
                    else
                        ($aw.task // "") as $task |
                        (if $aw.workingOnId then
                            ($bl | map(select(.id == $aw.workingOnId)) | first // null)
                         else
                            ($bl | map(
                                if .worktreeWindowId == $wid then .
                                elif ((.subitems // []) | map(select(.worktreeWindowId == $wid)) | length) > 0 then
                                    (.subitems | map(select(.worktreeWindowId == $wid)) | first)
                                else null end
                            ) | map(select(. != null)) | first // null)
                         end) as $item |
                        "\($task)\t\($item.id // "")\t\($item.title // "")"
                    end
                ' --arg wid "$window_id" -r 2>/dev/null)

                local task item_id item_title
                IFS=$'\t' read -r task item_id item_title <<< "$info"
                if [[ -n "$task" ]]; then
                    name="$task"
                elif [[ -n "$item_id" ]]; then
                    name="${item_id}: ${item_title}"
                fi
            fi
        fi
    fi

    # Source 3: first user message from transcript (only when kanban is silent).
    if [[ -z "$name" && -f "$transcript" ]]; then
        name=$(python3 - "$transcript" <<'PY'
import json, sys
try:
    with open(sys.argv[1]) as fp:
        for line in fp:
            try: p = json.loads(line)
            except Exception: continue
            if p.get('type') != 'user' or p.get('isSidechain'):
                continue
            c = (p.get('message') or {}).get('content')
            text = None
            if isinstance(c, str):
                text = c
            elif isinstance(c, list):
                for part in c:
                    if isinstance(part, dict) and part.get('type') == 'text':
                        text = part.get('text'); break
            if text:
                print(' '.join(text.split()))
                break
except Exception:
    pass
PY
        )
    fi

    # Collapse whitespace, strip pipes (record separator), cap at 40 chars.
    name="${name//$'\n'/ }"
    name="${name//$'\r'/ }"
    name="${name//|/ }"
    if (( ${#name} > 40 )); then
        name="${name:0:37}..."
    fi
    printf '%s' "$name"
}

# Save the most recent Claude session ID for the current tmux window, the
# display name derived from the MISSION panel state, and the current project
# dir so ccc can cd back to it on resume (XACA-0177). Sidecar file format is
# "<uuid>|<name>|<project_dir>" (pipe-delimited; name and dir may be empty).
# Skipped outside tmux — no per-window scope to attach to.
#
# XACA-0541 — Optional $1: a known session UUID (pinned via --session-id at
# launch). When supplied and valid, skips the ls -t heuristic entirely — no
# project_dir lookup needed. Callers that don't supply $1 keep the ls -t
# fallback, now guarded against claiming a uuid another window's sidecar owns
# (XACA-1074-004); ccc passes an id on both its --resume and --continue paths
# (XACA-1074-002/003).
_cc_save_session() {
    [[ -z "$SESSION_CODE" ]] && return 0

    local window_suffix
    window_suffix=$(_cc_window_suffix) || return 0

    # Accept an optional known UUID from the caller (e.g. _cc_launch pinned id).
    local _cc_known_id="${1:-}"

    local session_id=""
    local latest_file=""

    if [[ "$_cc_known_id" =~ ^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$ ]]; then
        # Fast path: use the pinned UUID directly; no filesystem probe needed.
        session_id="$_cc_known_id"
        # latest_file stays empty — _cc_derive_session_name handles that gracefully.
    else
        # Fallback path (used by ccc --resume / --continue): probe the project dir.
        local encoded_dir
        encoded_dir=$(_cc_encode_project_dir)
        local project_dir="$HOME/.claude/projects/-${encoded_dir}"

        [[ ! -d "$project_dir" ]] && return 0

        # Find the most recently modified session .jsonl file
        latest_file=$(ls -t "$project_dir"/*.jsonl 2>/dev/null | head -1)
        [[ -z "$latest_file" ]] && return 0

        session_id=$(basename "$latest_file" .jsonl)

        # Validate UUID format
        [[ "$session_id" =~ ^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$ ]] || return 0

        # XACA-1074-004: the newest transcript in a shared project dir is not
        # necessarily ours. If a DIFFERENT window's sidecar already records
        # this uuid, refuse the claim and leave our own sidecar as it was.
        # Every sidecar counts whatever its SESSION_CODE: distinct tmux
        # sessions (e.g. ...-command and ...-comms) can share one cwd and so
        # one project dir. Only real sidecar names are considered
        # (-w@<N>, legacy -w<index>, -k<key>); hand-made backups such as
        # *.bak-<stamp>, *.tmp or *~ hold stale uuids and must never block a
        # save. Only the first |-field is parsed, so this holds for both the
        # 3-field and the extended sidecar formats.
        local _cc_sib _cc_sib_id _cc_sib_base
        local _cc_sib_re='^[^.~]+-(w@?[0-9]+|k[A-Za-z0-9_@:%-]+)$'
        local _cc_own="$HOME/.claude/terminal-sessions/${SESSION_CODE}${window_suffix}"
        while IFS= read -r _cc_sib; do
            [[ -z "$_cc_sib" || "$_cc_sib" == "$_cc_own" ]] && continue
            _cc_sib_base="${_cc_sib##*/}"
            [[ "$_cc_sib_base" =~ $_cc_sib_re ]] || continue
            _cc_sib_id=""
            IFS='|' read -r _cc_sib_id _ < "$_cc_sib" 2>/dev/null
            if [[ "$_cc_sib_id" == "$session_id" ]]; then
                print -u2 "_cc_save_session: XACA-1074: session ${session_id} belongs to another window (${_cc_sib_base}); not claiming it for ${SESSION_CODE}${window_suffix}"
                return 0
            fi
        done < <(find "$HOME/.claude/terminal-sessions" -maxdepth 1 -type f 2>/dev/null)
    fi

    local session_name
    session_name=$(_cc_derive_session_name "$latest_file")

    # XACA-1075: record the tmux server identity + window id with the pointer
    # (new fields LAST — see _cc_sidecar_read) so a "-w@N" file can be proven
    # stale after a server restart. '|' in the name would shift every later
    # field, so it is flattened.
    # XACA-1074-022: the writer must never emit a file its own reader rejects. The
    # reader accepts a "-w@N" file only with a COMPLETE identity (start AND pid) from
    # this server, or as a legacy identity-less file on a pre-upgrade server. A
    # transient/ancient tmux that cannot answer #{start_time} or #{pid} would make
    # this writer emit start-only or identity-less files that are rejected forever
    # once tmux answers. So: no complete identity => do NOT write a "-w@N" pointer (the
    # existing sidecar is left untouched and a one-line notice says so; the window just
    # has no saved pointer yet). A "-k<key>" file never has its identity checked, so it
    # is still written, with BOTH identity fields blank rather than half-filled.
    local _cc_srv_start="" _cc_srv_pid="" _cc_wid _cc_id_ok=0 _cc_write_ok=1
    if _cc_live_server_id && [[ -n "$_CC_LIVE_PID" ]]; then
        _cc_srv_start="$_CC_LIVE_START"; _cc_srv_pid="$_CC_LIVE_PID"; _cc_id_ok=1
    fi
    _cc_wid=$(_cc_tmux_fmt '#{window_id}')
    session_name="${session_name//|/ }"
    if [[ "$window_suffix" == -w@* ]] && (( ! _cc_id_ok )); then
        _cc_write_ok=0
        print -u2 "_cc_save_session: XACA-1074-022: tmux server identity (start_time/pid) unreadable; not writing ${SESSION_CODE}${window_suffix} (an unprovable pointer would be rejected later; existing sidecar left untouched)"
    fi

    local _cc_target="$HOME/.claude/terminal-sessions/${SESSION_CODE}${window_suffix}"
    if (( _cc_write_ok )); then
        mkdir -p "$HOME/.claude/terminal-sessions"

        # XACA-1075: a "-w@N" file that cannot be proven to come from this server
        # lifetime belongs to whatever window held that id before a restart.
        # Overwriting it would destroy the only pointer to that stranded session, so
        # park it beside the key (".stray-<mtime>", no clobber) where
        # _cc_sidecar_stray_hint still lists it. "-k<key>" files are this window's own.
        if [[ "$window_suffix" == -w@* && -f "$_cc_target" ]] && ! _cc_sidecar_from_this_server "$_cc_target"; then
            local _cc_park _cc_base _cc_n=0
            _cc_base="${_cc_target}.stray-$(_cc_file_mtime "$_cc_target" || echo 0)"
            _cc_park="$_cc_base"
            while [[ -e "$_cc_park" ]] && (( _cc_n < 100 )); do
                _cc_n=$((_cc_n + 1)); _cc_park="${_cc_base}-${_cc_n}"
            done
            # Could not park it (no free name, or mv failed): skip the write rather
            # than clobber the only pointer to the stranded session.
            if [[ -e "$_cc_park" ]] || ! mv "$_cc_target" "$_cc_park" 2>/dev/null; then
                return 0
            fi
        fi

        printf '%s|%s|%s|%s|%s|%s\n' "$session_id" "$session_name" "$PWD" \
            "$_cc_srv_start" "$_cc_srv_pid" "$_cc_wid" \
            > "$_cc_target"
    fi

    # XACA-0279-011: per-account resume-id save (parallel to per-terminal save above).
    # Writes ~/.claude/.last-session-per-account/<account_id_safe>.txt so ccc() can
    # filter resume targets by account identity across terminal sessions.
    local account_id_env="${CLAUDE_ACTIVE_ACCOUNT_ID:-}"
    if [[ -n "$account_id_env" ]]; then
        # Replace non-alphanumeric chars with underscores for a safe filename
        local account_id_safe
        account_id_safe=$(printf '%s' "$account_id_env" | tr -cs 'a-zA-Z0-9' '_')
        mkdir -p "$HOME/.claude/.last-session-per-account"
        printf '%s\n' "$session_id" \
            > "$HOME/.claude/.last-session-per-account/${account_id_safe}.txt"
    fi
}

# Read the saved-session sidecar for the current tmux window and echo the
# display-name portion (empty if unset, missing, or legacy uuid-only file).
# Used by team banner scripts to render the "Saved Session:" line.
_cc_saved_session_label() {
    [[ -z "$SESSION_CODE" ]] && return 0

    local window_suffix
    window_suffix=$(_cc_window_suffix) || return 0

    local session_file="$HOME/.claude/terminal-sessions/${SESSION_CODE}${window_suffix}"
    [[ -f "$session_file" ]] || return 0

    # XACA-1075: same staleness guard as ccc, silently -- never show a banner
    # label for a session ccc would refuse to resume.
    _cc_sidecar_usable "$session_file" "$window_suffix" quiet || return 0

    local session_id saved_name saved_dir
    IFS='|' read -r session_id saved_name saved_dir _ _ _ < "$session_file"
    printf '%s' "$saved_name"
}

# XACA-1380-004: Claude LIVENESS marker. Written when claude is launched,
# removed when claude returns control to the shell (any rc, incl. Ctrl-C). A
# crash or power loss kills the shell first, so the marker survives and tells
# kb-host-ready (XACA-1380-005) which windows had a live conversation.
# Key = SESSION_CODE + _cc_window_suffix, i.e. exactly the XACA-1075 sidecar key
# (never a raw window id). Format (one pipe line, new fields LAST):
#   1|uuid|launch_pwd|socket|session_name|window_name|server_start|server_pid|set_epoch
# uuid is empty when no --session-id was pinned (005 treats that as low
# confidence). No tmux / no SESSION_CODE -> nothing written. Never fails the
# caller. NB: never name a local "path" -- in zsh it is tied to PATH (a `local
# path` empties PATH, so mkdir/mv/date silently vanish). Design: kanban/plans/XACA-1380/XACA-1380-001_design.md section 4.
_cc_live_marker_path() {
    [[ -n "$SESSION_CODE" ]] || return 1
    local sfx
    sfx=$(_cc_window_suffix 2>/dev/null) || return 1
    [[ -n "$sfx" ]] || return 1
    print -r -- "${KB_CLAUDE_LIVE_DIR:-$HOME/.aiteamforge/run/claude-live}/${SESSION_CODE}${sfx}"
}

_cc_live_marker_set() {
    local uuid="$1" mpath dir tmp sock sname wname
    mpath=$(_cc_live_marker_path) || return 0
    dir="${mpath:h}"
    mkdir -p "$dir" 2>/dev/null || return 0
    _cc_live_server_id || return 0
    sock=$(_cc_tmux_fmt '#{socket_path}'); sock="${sock:t}"
    sname=$(_cc_tmux_fmt '#{session_name}'); sname="${sname//|/ }"
    wname=$(_cc_tmux_fmt '#{window_name}'); wname="${wname//|/ }"
    tmp="${mpath}.tmp.$$"
    if printf '1|%s|%s|%s|%s|%s|%s|%s|%s\n' "$uuid" "${PWD//|/ }" "${sock//|/ }" "$sname" "$wname" \
        "$_CC_LIVE_START" "$_CC_LIVE_PID" "$(date +%s)" > "$tmp" 2>/dev/null; then
        mv -f "$tmp" "$mpath" 2>/dev/null || unlink "$tmp" 2>/dev/null
    else
        unlink "$tmp" 2>/dev/null
    fi
    return 0
}

_cc_live_marker_clear() {
    local mpath
    mpath=$(_cc_live_marker_path) || return 0
    unlink "$mpath" 2>/dev/null
    return 0
}

# XACA-0223 (ported from canonical claude_code_cc_aliases.sh — see FAULT C,
# XACA-1144): deterministic clear of the iTerm2 tab "C " prefix.
# The stop-hook daemon (kanban-stop.py) is a heuristic that can miss slow
# Claude shutdowns. Here we know `claude` has exited because its process
# returned — fire clear_claude_active synchronously. Refcount semantics
# still prevent over-clearing when multiple Claude sessions share a tab.
# Fallback chain matches the other three call sites (kanban-session-start.py,
# kanban-stop.py, update_claude_agent.sh): $DEV_TEAM_ROOT override first,
# since ~/dev-team never exists on a consumer, then ~/aiteamforge.
# Silent no-op when the helper is absent — this file is sourced into every
# interactive shell, so a missing helper must never break the terminal.
_cc_clear_claude_active() {
    local _cc_badge_helper=""
    if [[ -n "${DEV_TEAM_ROOT:-}" && -f "${DEV_TEAM_ROOT}/iterm2_badge_helper.sh" ]]; then
        _cc_badge_helper="$DEV_TEAM_ROOT/iterm2_badge_helper.sh"
    elif [[ -f "$HOME/dev-team/iterm2_badge_helper.sh" ]]; then
        _cc_badge_helper="$HOME/dev-team/iterm2_badge_helper.sh"
    elif [[ -f "$HOME/aiteamforge/iterm2_badge_helper.sh" ]]; then
        _cc_badge_helper="$HOME/aiteamforge/iterm2_badge_helper.sh"
    fi
    if [[ -n "$_cc_badge_helper" ]]; then
        source "$_cc_badge_helper" && clear_claude_active
    fi
}

# Helper: launch Claude Code with a system prompt file
# Uses direct argument passing (NOT stdin piping, which breaks in tmux)
# Set CC_DEBUG=1 for preview only
_cc_launch() {
    local prompt_file="$1"

    # XACA-0977 BLOCKING A parity (dev claude_code_cc_aliases.sh): a GLOBAL,
    # out-of-band signal telling cc() whether claude was ever actually
    # invoked, separate from this function's return code. Pre-clear FIRST —
    # before any early-abort path below — so a stale "1" from a PRIOR
    # successful call in this shell can't leak through.
    _CC_LAUNCH_INVOKED=0

    # Read prompt text directly
    if [[ ! -f "$prompt_file" ]]; then
        echo "ERROR: Prompt file not found: $prompt_file" >&2
        return 1
    fi

    # XACA-1312 (design doc §4, site #1): resolve and apply the team's
    # declared ai.credential right after the prompt-file checks, via the
    # SAME shared core dev claude_code_cc_aliases.sh uses. A missing core
    # (partial upgrade, or a non-zsh shell) refuses rather than launching
    # unrouted (design §6) -- UNLESS AITEAMFORGE_ALLOW_DEFAULT_OAUTH=1, in
    # which case _cc_routing_core_missing itself returns 0 and we fall
    # through with the token/id locals left empty (default OAuth, per
    # fix round 1 / bot review on PR #957).
    local _CC_RESOLVED_TOKEN="" _CC_RESOLVED_AUTH_TYPE=""
    local _CC_BILLED_ID="" _CC_BILLED_NICKNAME=""
    if _cc_routing_core_complete; then
        _cc_route_prepare
        if [[ $? -eq 1 ]]; then
            echo "ERROR: Cannot resolve Anthropic token for this team — aborting launch" >&2
            return 1
        fi
    elif ! _cc_routing_core_missing; then
        return 1
    fi

    CLAUDE_SYSTEM_PROMPT="$(<"$prompt_file")"

    if [[ -z "$CLAUDE_SYSTEM_PROMPT" ]]; then
        echo "ERROR: CLAUDE_SYSTEM_PROMPT is empty after reading $prompt_file" >&2
        return 1
    fi

    # --- XACA-0541: session name -------------------------------------------
    # Start from caller-supplied env var; fall back to kanban/transcript derive.
    local _cc_name="${CC_SESSION_NAME:-}"
    if [[ -z "$_cc_name" ]]; then
        _cc_name=$(_cc_derive_session_name "")
    fi
    # Sanitize regardless of source: collapse newlines/whitespace, strip pipes,
    # cap at 40 chars (mirrors the sanitize block in _cc_derive_session_name).
    _cc_name="${_cc_name//$'\n'/ }"
    _cc_name="${_cc_name//$'\r'/ }"
    _cc_name="${_cc_name//|/ }"
    if (( ${#_cc_name} > 40 )); then
        _cc_name="${_cc_name:0:37}..."
    fi

    # --- XACA-0541: pinned session-id --------------------------------------
    # XACA-1300-027 (Tap-Only-Edit: intentional -- this file has no
    # sync-tap mapping, see CONTRIBUTING; hand-kept in parity with dev
    # claude_code_cc_aliases.sh): shared, memoized probe now provided by
    # cc-account-routing.sh (synced), instead of a standalone `claude
    # --help` fork here. cc()'s two fallback branches below share the same
    # memoized answer, so `claude --help` runs at most once per shell.
    local _cc_pinned_id=""
    if _cc_probe_has_session_id; then
        _cc_pinned_id=$(uuidgen | tr 'A-Z' 'a-z')
    fi

    if [[ "$CC_DEBUG" == "1" ]]; then
        echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
        echo "CC_DEBUG=1 — Preview Only"
        echo "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━"
        echo "Prompt file: $prompt_file"
        echo "Prompt length: ${#CLAUDE_SYSTEM_PROMPT} chars"
        echo "Session name: ${_cc_name:-(none)}"
        echo "Pinned session-id: ${_cc_pinned_id:-(none — feature not supported)}"
        echo ""
        echo "First 500 chars:"
        echo "${CLAUDE_SYSTEM_PROMPT:0:500}"
        echo "..."
        return 0
    fi

    # XACA-1312 (design doc §0 D3 correction, §4 CLAUDE_BILLED_ACCOUNT_ID
    # contract): record via the shared helper with the GATED billed
    # identity _cc_route_prepare just resolved — NOT the old headless
    # helper's own recording rule, which reads CLAUDE_BILLED_ACCOUNT_ID from
    # the CALLING shell's environment. That is empty even on a successful
    # route: the token only ever reaches claude's CHILD env via
    # _cc_run_claude_with_auth's subshell, so the headless helper's rule 1
    # would have recorded every routed tap launch as default OAuth —
    # exactly the mis-record this ticket exists to fix. Record at LAUNCH
    # time (crash-safe, XACA-0668 parity) using the local pin above.
    _cc_record_session_account "$_cc_pinned_id" "$_CC_BILLED_ID" "$_CC_BILLED_NICKNAME"

    # Build optional flag array — empty values are simply omitted.
    local -a _cc_extra_args=()
    [[ -n "$_cc_name" ]] && _cc_extra_args+=(--name "$_cc_name")
    [[ -n "$_cc_pinned_id" ]] && _cc_extra_args+=(--session-id "$_cc_pinned_id")

    # XACA-1312: from here on claude is genuinely being invoked (dev parity)
    # -- flip the signal BEFORE the call, and inject the resolved credential
    # via the shared scoped-env helper instead of a bare `claude` call.
    _cc_live_marker_set "$_cc_pinned_id"   # XACA-1380-004
    _CC_LAUNCH_INVOKED=1
    _cc_run_claude_with_auth "$_CC_RESOLVED_TOKEN" "$_CC_RESOLVED_AUTH_TYPE" \
        --permission-mode bypassPermissions "${_cc_extra_args[@]}" --append-system-prompt "$CLAUDE_SYSTEM_PROMPT" \
        "If an AMB heartbeat system reminder is present, call mcp__amb__heartbeat first, then introduce yourself briefly."
    local _cc_launch_claude_rc=$?
    _cc_live_marker_clear   # XACA-1380-004 (clean return; a crash leaves it)

    # Pass the pinned UUID so _cc_save_session can skip the ls -t heuristic.
    _cc_save_session "$_cc_pinned_id"

    # XACA-1312: post-exit record too (dev _cc_launch parity) — a session
    # may be resumable even after a non-zero exit, and billing already
    # occurred either way.
    _cc_record_session_account "$_cc_pinned_id" "$_CC_BILLED_ID" "$_CC_BILLED_NICKNAME"

    if command -v kb-clear &> /dev/null; then
        kb-clear
    fi
    _cc_clear_claude_active
    return $_cc_launch_claude_rc
}

# Context-aware cc command — detects terminal SESSION_TYPE/SESSION_NAME and
# uses the appropriate persona. Falls back to plain claude if not configured.
cc() {
    if [[ -n "$SESSION_TYPE" && -n "$SESSION_NAME" ]]; then
        local dir="${SESSION_DIR:-$SESSION_TYPE}"
        local prompt_file="$AITEAMFORGE_DIR/${dir}/scripts/prompts/${SESSION_TYPE}-${SESSION_NAME}-prompt.txt"
        if [[ -f "$prompt_file" ]]; then
            _cc_launch "$prompt_file"
            return
        else
            # XACA-0785: this branch used to silently drop straight through to
            # the persona-less fallback below — no error, no persona, and
            # nothing in colors/tmux window name/banners to reveal it. That
            # silent no-op was the core XACA-0785 bug. Warn loudly instead.
            echo "🚨 WARNING: Agent prompt file not found: $prompt_file" >&2
            echo "🚨 Falling back to plain claude — NO PERSONA (generic assistant, no character/team context)." >&2
        fi
    fi
    # XACA-1312 (design §4 site #2): plain-claude fallback -- the headless
    # gate path (`printf prompt | cc` from kb-run-* with no persona context)
    # AND the "prompt file not found" fallthrough above. Route it too,
    # whenever a team context exists, via the SAME shared core.
    local _cc_fb_team="${SESSION_TYPE:-${LCARS_TEAM:-${KB_TEAM:-}}}"
    if [[ -n "$_cc_fb_team" ]]; then
        # XACA-1312 fix round 1: same missing-core override handling as
        # site #1 above -- _cc_routing_core_missing returns 0 under
        # AITEAMFORGE_ALLOW_DEFAULT_OAUTH=1 and we fall through unrouted.
        local _CC_RESOLVED_TOKEN="" _CC_RESOLVED_AUTH_TYPE=""
        local _CC_BILLED_ID="" _CC_BILLED_NICKNAME=""
        if _cc_routing_core_complete; then
            _cc_route_prepare
            if [[ $? -eq 1 ]]; then
                # XACA-1312 §3.3: REFUSED. claude must NOT run at all -- a
                # refusal is not a persona failure, and falling back to
                # plain unrouted claude here would reconstruct the exact
                # silent-downgrade defect this ticket exists to close.
                echo "ERROR: Cannot resolve Anthropic token for team '${_cc_fb_team}' — aborting launch" >&2
                return 1
            fi
        elif ! _cc_routing_core_missing; then
            return 1
        fi
        # Pin a session id the same way _cc_launch does (XACA-0541), when cc
        # got NO arguments, OR (XACA-1300-028, Tap-Only-Edit: intentional --
        # parity with dev claude_code_cc_aliases.sh) when the only relevant
        # flag is print mode (-p/--print) and the caller hasn't already
        # taken session identity into their own hands -- see
        # _cc_fb_wants_pinned_sid's own comment (cc-account-routing.sh) for
        # the exact rule. With `cc --resume <id>`, `cc -c` or a subcommand
        # an added --session-id would conflict or break the command, so
        # those are excluded. XACA-1300-027: the supported-flag check is
        # the shared memoized probe, not a standalone fork.
        local -a _cc_fb_extra=()
        local _cc_fb_sid=""
        if _cc_fb_wants_pinned_sid "$@" && _cc_probe_has_session_id; then
            _cc_fb_sid=$(uuidgen | tr 'A-Z' 'a-z')
            _cc_fb_extra=(--session-id "$_cc_fb_sid")
        fi
        _cc_live_marker_set "$_cc_fb_sid"   # XACA-1380-004
        _cc_run_claude_with_auth "$_CC_RESOLVED_TOKEN" "$_CC_RESOLVED_AUTH_TYPE" \
            --permission-mode bypassPermissions "${_cc_fb_extra[@]}" "$@"
        local _cc_fb_rc=$?
        _cc_live_marker_clear   # XACA-1380-004
        # XACA-1312 D3 correction: record via the gated identity, never the
        # headless helper's own rule (see _cc_launch's matching comment).
        _cc_record_session_account "$_cc_fb_sid" "$_CC_BILLED_ID" "$_CC_BILLED_NICKNAME"
        return $_cc_fb_rc
    fi

    # XACA-1300-014: no team context -- nothing declared to route. Keep the
    # headless helper exactly as before; it correctly attributes a NESTED
    # headless launch (one shelled out from inside an already-routed parent
    # session) via CLAUDE_BILLED_ACCOUNT_ID inherited from that parent's
    # export. When cc got NO arguments, OR (XACA-1300-028, Tap-Only-Edit:
    # intentional -- parity with dev) print mode with no caller-managed
    # session flags -- see _cc_fb_wants_pinned_sid's comment for the exact
    # rule. `cc --resume <id>`, `cc -c` and subcommands would break or
    # conflict with an added --session-id, so those stay unrecorded.
    # </dev/null keeps the helper's `claude --help` probe off the piped
    # gate prompt. XACA-1300-027: gate on the shared memoized probe FIRST
    # so the helper (which would just re-probe the identical thing and
    # silently no-op) is never even invoked when --session-id is
    # unsupported.
    local -a _cc_fb_args=()
    if _cc_fb_wants_pinned_sid "$@" && _cc_probe_has_session_id \
        && [[ -x "$AITEAMFORGE_DIR/scripts/session-account-map-headless.sh" ]]; then
        local _cc_fb_sid2
        _cc_fb_sid2=$("$AITEAMFORGE_DIR/scripts/session-account-map-headless.sh" </dev/null)
        [[ -n "$_cc_fb_sid2" ]] && _cc_fb_args=(--session-id "$_cc_fb_sid2")
    fi
    claude --permission-mode bypassPermissions "${_cc_fb_args[@]}" "$@"
}

# Resume the most recent Claude session for THIS terminal
# Uses stored session ID instead of --continue (which picks most recent globally)
ccc() {
    # XACA-1312 (design §5): argument parsing + routing + cross-account
    # guard parity with dev ccc(). A typo like `ccc --forse` must be a usage
    # error, not silent consent-absent.
    local _ccc_force=0
    while (( $# )); do
        case "$1" in
            --force) _ccc_force=1; shift ;;
            *)
                print -u2 "ccc: unknown argument '$1'"
                print -u2 "usage: ccc [--force]"
                return 2
                ;;
        esac
    done

    # XACA-0668 / XACA-1075: migrate this window's legacy "-w<index>" /
    # "-w<window_id>" sidecar to the current key BEFORE we compute the suffix
    # and read the file, so resume finds the migrated pointer instead of falling
    # through to --continue. No-op outside tmux / without SESSION_CODE.
    _cc_migrate_window_sidecar

    # Resolve credentials BEFORE reading the sidecar (ordering is
    # load-bearing — see dev ccc()'s own comment on this: the recorder must
    # never run against a pre-resolution empty billed id).
    #
    # XACA-1312 fix round 1: missing core is no longer an unconditional
    # refusal here either -- _cc_routing_core_missing returns 0 under
    # AITEAMFORGE_ALLOW_DEFAULT_OAUTH=1, treated the same as a successful
    # (unrouted, default-OAuth) _cc_route_prepare rc=0 below.
    local _CC_RESOLVED_TOKEN="" _CC_RESOLVED_AUTH_TYPE=""
    local _CC_BILLED_ID="" _CC_BILLED_NICKNAME=""
    local _ccc_cred_rc
    if _cc_routing_core_complete; then
        _cc_route_prepare
        _ccc_cred_rc=$?
    else
        if ! _cc_routing_core_missing; then
            return 1
        fi
        _ccc_cred_rc=0
    fi
    local resolved_account_id="$_CC_BILLED_ID"
    local resolved_account_nickname="$_CC_BILLED_NICKNAME"

    # --- D3 parity: rc=1 is fail-closed, UNCONDITIONALLY — --force does NOT
    # override. Consenting to bill account X is meaningless when no token
    # for X could be obtained.
    if [[ $_ccc_cred_rc -eq 1 ]]; then
        echo "ERROR: Cannot resolve Anthropic token — aborting resume (no session was resumed, nothing was billed)" >&2
        return 1
    fi

    local window_suffix
    window_suffix=$(_cc_window_suffix) || window_suffix=""
    local session_file="$HOME/.claude/terminal-sessions/${SESSION_CODE}${window_suffix}"

    # XACA-1075: _cc_sidecar_usable fails closed (one-line notice, file left
    # alone) when the transcript is gone or a "-w@N" file cannot be proven to
    # belong to this tmux server lifetime -- falls through to --continue below.
    # (It also replaces the XACA-1074-018 phantom-sidecar self-heal that used to
    # sit here: the same transcript test now lives in the gate itself.)
    if [[ -n "$SESSION_CODE" && -n "$window_suffix" && -f "$session_file" ]] \
        && _cc_sidecar_usable "$session_file" "$window_suffix"; then
        # Sidecar is "<uuid>|<name>|<project_dir>|<server_start>|<server_pid>|
        # <window_id>" -- legacy 1/2/3-field files parse with empty trailing
        # vars and still work with --resume. All 6 fields are read so the
        # identity fields never fold into saved_dir.
        local session_id saved_name saved_dir
        IFS='|' read -r session_id saved_name saved_dir _ _ _ < "$session_file"
        if [[ -n "$session_id" ]]; then
            # XACA-0977 D1/D2 parity: cross-account resume guard, via the
            # shared helper (design §1.1, §5) — same implementation dev ccc
            # uses. On a mismatch with no --force it has already printed the
            # full warning; this function's only job is to return.
            if ! _cc_resume_account_guard "$session_id" "$resolved_account_id" "$_ccc_force"; then
                return 1
            fi

            # XACA-0177: restore project dir so claude --resume sees the
            # same cwd that was active when the session was saved.
            if [[ -n "$saved_dir" && "$saved_dir" != "$PWD" ]]; then
                if [[ -d "$saved_dir" ]]; then
                    cd "$saved_dir" || echo "ccc: warning — cd '$saved_dir' failed, resuming from $PWD" >&2
                else
                    echo "ccc: warning — saved project dir '$saved_dir' is gone, resuming from $PWD" >&2
                fi
            fi

            _cc_save_session "$session_id"
            _cc_record_session_account "$session_id" "$resolved_account_id" "$resolved_account_nickname"

            # XACA-1303: never-blocking resume cost warning. Optional — guarded
            # with `command -v` (not the completeness gate) so a stale or
            # missing routing core skips it silently instead of breaking resume.
            command -v _cc_resume_context_warning >/dev/null 2>&1 && \
                _cc_resume_context_warning "$session_id"

            _cc_live_marker_set "$session_id"   # XACA-1380-004
            _cc_run_claude_with_auth "$_CC_RESOLVED_TOKEN" "$_CC_RESOLVED_AUTH_TYPE" \
                --permission-mode bypassPermissions --resume "$session_id"
            local _ccc_claude_rc=$?
            _cc_live_marker_clear   # XACA-1380-004
            # XACA-1074-002: pass the id this branch already resumed. The bare
            # call fell back to `ls -t` on the shared project dir, so windows
            # sharing a cwd stamped each other's newest transcript here.
            # XACA-1074-018: only if claude actually left a transcript for this
            # id; re-stamping a phantom (or one that vanished) is what wedged
            # the window. Absent -> no write, any existing sidecar stays.
            if _cc_transcript_exists "$session_id"; then
                _cc_save_session "$session_id"
            else
                print -u2 "ccc: XACA-1074-018: no transcript for ${session_id}; not saving it for ${SESSION_CODE}${window_suffix}"
            fi
            _cc_record_session_account "$session_id" "$resolved_account_id" "$resolved_account_nickname"
            if command -v kb-clear &> /dev/null; then
                kb-clear
            fi
            _cc_clear_claude_active
            return $_ccc_claude_rc
        fi
    fi

    # XACA-1303: no resume cost warning here — no session id to locate a
    # transcript by until claude has already picked one.
    # XACA-1075: list (never adopt) unclaimed same-cwd sidecars for an explicit resume.
    _cc_sidecar_stray_hint
    print -u2 $'\e[2m'"ccc: no saved session for this window — using --continue; billed to ${resolved_account_nickname:-default OAuth}"$'\e[0m'
    # XACA-1074-003: pin a fresh session id so the post-exit save needn't guess
    # via `ls -t` (windows sharing a cwd share one project dir, so the newest
    # transcript is routinely another window's). claude rejects --session-id
    # with --continue unless --fork-session accompanies it, so the pin forks
    # the continued conversation into a NEW session this window owns. Both
    # flags are feature-detected; if either is missing we keep the bare
    # --continue and rely on _cc_save_session's sibling-sidecar guard.
    local -a _ccc_cont_args=(--continue)
    local _ccc_cont_sid=""
    if _cc_probe_has_session_id && claude --help 2>/dev/null | grep -q -- "--fork-session"; then
        _ccc_cont_sid=$(uuidgen | tr 'A-Z' 'a-z')
        _ccc_cont_args=(--continue --fork-session --session-id "$_ccc_cont_sid")
    fi
    _cc_live_marker_set "$_ccc_cont_sid"   # XACA-1380-004 (4th site: ccc --continue)
    _cc_run_claude_with_auth "$_CC_RESOLVED_TOKEN" "$_CC_RESOLVED_AUTH_TYPE" \
        --permission-mode bypassPermissions "${_ccc_cont_args[@]}"
    local _ccc_claude_rc=$?
    _cc_live_marker_clear   # XACA-1380-004
    # XACA-1074-018: a pinned id is only real if claude wrote its transcript.
    # `--continue` with no prior conversation exits 1 ("No conversation found
    # to continue") and creates nothing, and a user who quits before the first
    # message may leave nothing either; saving the pin then plants a phantom.
    # Skip the save entirely in that case. The unpinned fallback keeps the bare
    # save (probe + sibling guard), which finds real transcripts only.
    if [[ -z "$_ccc_cont_sid" ]]; then
        _cc_save_session
    elif _cc_transcript_exists "$_ccc_cont_sid"; then
        _cc_save_session "$_ccc_cont_sid"
    else
        print -u2 "ccc: XACA-1074-018: claude left no transcript for pinned session ${_ccc_cont_sid} (rc=${_ccc_claude_rc}); not saving it"
    fi
    if command -v kb-clear &> /dev/null; then
        kb-clear
    fi
    _cc_clear_claude_active
    return $_ccc_claude_rc
}

